anchors=[(3,4),(8,11),(13,6)]
h,w=17,19
g=[[0]*w for _ in range(h)]
for r,c in anchors:
    # top cap
    for j in range(c-2,c+3):
        if 0<=r-2<h and 0<=j<w: g[r-2][j]=5
    # second row
    for j,v in [(c-2,2),(c,5),(c+2,2)]:
        if 0<=r-1<h and 0<=j<w: g[r-1][j]=v
    # anchor row
    for j in (c-2,c+2):
        if 0<=r<h and 0<=j<w: g[r][j]=2
    if 0<=r<h and 0<=c<w: g[r][c]=3
    # lower side row
    for j in (c-2,c+2):
        if 0<=r+1<h and 0<=j<w: g[r+1][j]=2
    # horizontal base/ray: 2 everywhere except 5-wide 8 segment
    if 0<=r+2<h:
        for j in range(w): g[r+2][j]=2
        for j in range(c-2,c+3):
            if 0<=j<w: g[r+2][j]=8
print('\n'.join(' '.join(map(str,row)) for row in g))
